head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[autoComplete > P > chooseOptionValue]<br/>chooseOption='true' 일때 추가되는 '선택 안내' 아이템의 Value 를 설정합니다.",
    "validation" : [
        "속성값 설정 시, '선택 안내' 아이템의 Value 를 설정합니다.",
        "값을 설정하지 않으면 ''(Empty String)이 적용됩니다.",
        "changeChooseOption() 메소드를 사용하여 Value 값을 동적으로 수정할 수 있습니다.",
        "'선택 안내' 아이템을 선택하면 컴포넌트의 Value 값은 chooseOptionValue 속성에 설정한 값으로 설정되며, 바인딩된 DataCollection 에도 이 값이 반영됩니다.",
        "값을 설정하지 않으면 '선택 안내' 아이템 선택 시 Value 값이 ''(Empty String)이 되어 mandatory='true' 일때 입력값 유효성 체크를 통과하지 못합니다.",
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 아이템 DataList 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' baseNode="list" repeatNode="map" id="dlt_city">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="label" name="label" dataType="text"></w2:column>';
    strDlt += '<w2:column id="value" name="value" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_city.setJSON([
        { "label" : "Incheon", "value" : "3" },
        { "label" : "Seoul", "value" : "1" },
        { "label" : "Busan", "value" : "4" },
        { "label" : "Sejong", "value" : "2" }
    ]);

    // target1 의 Value 가 반영될 DataMap 생성 (ref 바인딩 대상)
    let strDm = '';
    strDm += '<w2:dataMap ' + $c.gcm.getNameSpace() + ' baseNode="map" id="dm_ref">';
    strDm += '<w2:keyInfo>';
    strDm += '<w2:key id="city" name="city" dataType="text"></w2:key>';
    strDm += '</w2:keyInfo>';
    strDm += '</w2:dataMap>';
    $p.data.create(strDm);

    // 전제(chooseOption, mandatory)는 충족값 true, 검증 대상 속성은 의미 있는 값으로 초기 선택
    con_chooseOption.setValue("2");
    con_chooseOptionValue.setValue("0");
    con_mandatory.setValue("2");

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제]\n- 아이템(DataList 순서) : Incheon(3) / Seoul(1) / Busan(4) / Sejong(2)\n- Target 은 DataMap(dm_ref) 의 city 에 바인딩, Target 재생성 직전에 city 값을 빈 값으로 초기화 (생성 직후 선택된 아이템의 Value 가 city 에 반영됨)\n[절차]\n1. 조건 선택 -> Target 재생성 -> 아이템 확인\n2. 화살표 버튼으로 목록을 열어 Seoul 선택 -> 선택 값 확인\n3. 목록에서 첫번째(선택 안내) 아이템 선택 -> 선택 값 확인 -> validate\n4. newValue 입력 -> changeChooseOption"', '', 'label1');

    // 재생성할 때마다 같은 상태에서 시작하도록 바인딩 값 초기화
    dm_ref.set("city", "");

    // gdl_boolean 은 getText 로 읽는다 (미설정은 createCList 가 속성에서 제외)
    let properties = {
        chooseOption : con_chooseOption.getText(),
        chooseOptionValue : con_chooseOptionValue.getValue(),
        mandatory : con_mandatory.getText(),
        ref : "data:dm_ref.city",
    }

    let cList = $c.gcm.createCList(properties);

    let strTarget = '';
    strTarget += '<w2:autoComplete ' + $c.gcm.getNameSpace() + ' ' + cList + ' style="width:200px; height:30px;">';
    strTarget += '<w2:choices>';
    strTarget += '<w2:itemset nodeset="data:dlt_city">';
    strTarget += '<w2:label ref="label"></w2:label>';
    strTarget += '<w2:value ref="value"></w2:value>';
    strTarget += '</w2:itemset>';
    strTarget += '</w2:choices>';
    strTarget += '</w2:autoComplete>';

    await $p.dynamicCreate("target1", "autoComplete", strTarget, $c.gcm.getTestGroup());
}



// 아이템 인덱스별 Label (Value) 와 입력창 표시값 출력 (validation 1 ~ 3)
scwin.btn_getItemInfo_onclick = function (e) {
    let arrItem = [];
    for (let i = 0; i < target1.getItemCount(); i++) {
        let item = target1.getItem(i);
        arrItem.push("[" + i + "] " + item.label + " (" + item.value + ")");
    }
    wf_body_bottom.getObj("scwin").setReturnValue("아이템 : " + arrItem.join(" / "));
    wf_body_bottom.getObj("scwin").setReturnValue("입력창 표시값 : " + document.querySelector("[id='" + target1.id + "_label']").textContent);
};



// 컴포넌트 Value 와 바인딩된 DataMap 의 값 출력 (validation 4)
scwin.btn_getValueInfo_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("컴포넌트 Value : " + target1.getValue() + " / DataMap(dm_ref) city 값 : " + dm_ref.get("city"));
};



// 입력값 유효성 체크 결과 출력 (validation 5)
scwin.btn_validate_onclick = function (e) {
    let strValue = target1.getValue();
    wf_body_bottom.getObj("scwin").setReturnValue("Value : " + strValue + " -> validate() : " + target1.validate());
};



// '선택 안내' 아이템의 Value 변경 (validation 3)
//  - changeChooseOption(newValue, newLabel) : Label 은 기본값 -선택- 유지
scwin.btn_changeChooseOption_onclick = function (e) {
    target1.changeChooseOption(par_newValue.getValue(), "-선택-");
    scwin.btn_getItemInfo_onclick();
};
